//////////////////////////////////////////////////////////////////////
//
// Randomized H-curves, mla 2023.
//
// Inspired by https://www.shadertoy.com/view/mlS3Rm by MartyMcFly
// but a completely different tiling based method. See references
// therein for more details.
//
// 'a': fixed alignment of H's
// 'b': 'alternating' alignment
// 'c': no fill colour
// 'x': progressive scale
// 'y': progressive fill
// 'z': zoom in one level
//
//////////////////////////////////////////////////////////////////////

int N = 63;       // Work with NxN array of tiles
int maxdepth = 1024; // Maximum depth of joining

int bbit(int n) {
  // Result has a 1-bit at position of rightmost zero in n
  // ..xxx0111.. -> ..XXX1000.. & ..xxx1000.. -> ..0001000..
  return ~n & (n+1);
}

int check(ivec2 p) {
  int x = p.x, y = p.y;
  // Is the joiner block at (x,y) horizontal or vertical?
  // Return 0 for horizontal, 1 for vertical
  if (key(CHAR_B)) {
    // Alternate at each level - experimental
    int bb = bbit(x);
    assert(bb == bbit(y));
    int res = 1;
    while (bb != 0) { res = 1-res; bb >>= 1; } // use popcnt!
    return res;
  }
  if (key(CHAR_A)) return 0;
  uint h = ihash(uint(x)^ihash(uint(y)^uint(iTime)));
  return int(h&1u);
}

int ttype(ivec2 ix) {
  // Get tile type at index ix, there are tiles at all even coordinates.
  // (2a,2b), then tiles are joined together by "joiner blocks" at
  // (2a,2b+1),(2a+1,2b+1),(2a+2,2b+1) (or same with x,y flipped).
  // The central tile of a joiner block has the same number of trailing
  // 1s in the x and y coordinate (ie. bbit(x) == bbit(y)).
  // check(x,y) says if the joiner block centred on (x,y) is
  // horizontal or vertical.
  int x = ix.x, y = ix.y;
  if (x < 0 || y < 0) return 0;
  if (x >= N || y >= N) return 0;
  int bbx = bbit(x), bby = bbit(y);
  if (bbx == bby && (bbx == 1 || bbx < maxdepth)) return 1;
  int blocktype = -1; ivec2 block;
  if (bby > 1 && bby < maxdepth) {
    int bbx0 = bbit(x-1), bbx1 = bbit(x+1);
    if (bbx0 == bby) { blocktype = 0; block = ivec2(x-1,y); }
    if (bbx1 == bby) { blocktype = 0; block = ivec2(x+1,y); }
  }
  if (bbx > 1 && bbx < maxdepth) {
    int bby0 = bbit(y-1), bby1 = bbit(y+1);
    if (bbx == bby0) { blocktype = 1; block = ivec2(x,y-1); }
    if (bbx == bby1) { blocktype = 1; block = ivec2(x,y+1); }
  }
  if (blocktype < 0) return 0;
  return int(check(block) == blocktype);
}

void mainImage(out vec4 fragColor, vec2 fragCoord) {
  if (key(CHAR_X)) N = (1<<(int(mod(iTime,8.0)+1.0)))-1;
  if (key(CHAR_Y)) maxdepth = 1<<int(mod(iTime,8.0));
  if (key(CHAR_Z)) N = 2*N+1;
  float lwidth = 0.02;
  vec2 p = 1.05*(2.0*fragCoord-iResolution.xy)/iResolution.y;
  p += 1.0;
  p *= 0.5*float(N);
  float px = fwidth(p.x);
  vec3 col = vec3(0.8);
  if (min(p.x,p.y) > -0.5 && max(p.x,p.y) < float(N)+0.5) {
    ivec2 ix = ivec2(floor(p));
    p = fract(p);
    int tt = ttype(ix);
    // Now find adjacent tile type
    float dx0 = p.x, dx1 = 1.0-p.x;
    float dy0 = p.y, dy1 = 1.0-p.y;
    float d = min(min(dx0,dx1),min(dy0,dy1));
    ivec2 delta;
    if (d == dx0) delta = ivec2(-1,0);
    if (d == dx1) delta = ivec2(1,0);
    if (d == dy0) delta = ivec2(0,-1);
    if (d == dy1) delta = ivec2(0,1);
    int tt1 = ttype(ix+delta);
    if (!key(CHAR_C) && tt != 0) col = vec3(1,1,0.1);
    p = min(p,1.0-p);
    if (tt != tt1) {
      col *= smoothstep(0.0,px,min(p.x,p.y)-lwidth);
    }
    col *= smoothstep(0.0,px,length(p)-1.4*lwidth);
  }
  col = pow(col,vec3(0.4545));
  if (alert) col.r = 1.0;
  fragColor = vec4(col,1);
}

common_code:
bool alert = false;
void assert(bool b) {
  if (!b) alert = true;
}

const int CHAR_A = 65;
const int CHAR_B = 66;
const int CHAR_C = 67;
const int CHAR_X = 88;
const int CHAR_Y = 89;
const int CHAR_Z = 90;

#define key(code) (texelFetch(iChannel3, ivec2((code),2),0).x != 0.0)

// From Chris Wellons: https://nullprogram.com/blog/2018/07/31/
uint ihash(uint x) {
  x += 0x12345678u;
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    return x;
}
